import React from 'react'
import "./Header.scss"


const Header = () => {
    const { login, register } = useKindeAuth();

  return (
    <div className="container">
        <button onClick={register} type="button">Register</button>
        <button onClick={login} type="button">Log In</button>
    </div>
  )
}

export default Header
